import { Column, Entity, PrimaryGeneratedColumn } from 'typeorm';
import { BaseWithoutTenantEntity } from 'src/common/entity/base-without-tenant.entity';
import { GuideCrisisScope } from '../enum/guide.enum';

/**
 * The FIXED crisis copy, per language (plan §6.3). Written and approved by a
 * clinician — never generated by a model and never editable by the learning
 * loop. One active row per (scope, tenant, language); a tenant row overrides
 * the platform row, and English is the fallback.
 */
@Entity('guide_crisis_responses')
export class GuideCrisisResponse extends BaseWithoutTenantEntity {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ type: 'varchar', length: 12 })
  scope!: GuideCrisisScope;

  @Column({ name: 'tenant_id', type: 'varchar', nullable: true })
  tenantId?: string | null;

  @Column({ type: 'varchar', length: 16 })
  languageCode!: string;

  @Column({ type: 'text' })
  body!: string;

  @Column({ type: 'int', default: 1 })
  version!: number;

  @Column({ type: 'boolean', default: true })
  active!: boolean;

  @Column({ type: 'int', nullable: true })
  approvedBy?: number | null;

  @Column({ type: 'timestamp', nullable: true })
  approvedAt?: Date | null;
}
